CREATE OR REPLACE FUNCTION public.accept_connect_manager_invitation(p_token text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
declare
  v_uid uuid := auth.uid();
  v_email text := lower(trim(coalesce(auth.jwt() ->> 'email','')));
  v_inv public.connect_manager_invitations%rowtype;
  v_assignment_id uuid;
begin
  if v_uid is null or v_email = '' then
    raise exception 'É necessário iniciar sessão para aceitar o convite.';
  end if;
  if p_token is null or length(p_token) < 32 or length(p_token) > 256 then
    raise exception 'Convite inválido ou expirado.';
  end if;

  select * into v_inv
  from public.connect_manager_invitations
  where token_hash = encode(extensions.digest(p_token, 'sha256'), 'hex')
  for update;

  if not found or v_inv.status <> 'pending' or v_inv.expires_at <= now()
     or lower(v_inv.invited_email) <> v_email then
    raise exception 'Convite inválido, expirado, já utilizado ou destinado a outro email.';
  end if;

  update public.connect_manager_invitations
     set status = 'accepted',
         accepted_by = v_uid,
         accepted_at = now(),
         activated_at = now(),
         updated_at = now()
   where id = v_inv.id;

  select id into v_assignment_id
  from public.connect_manager_assignments
  where user_id = v_uid
    and country_code = v_inv.country_code
    and manager_role = v_inv.invited_role
  order by assigned_at desc
  limit 1
  for update;

  if v_assignment_id is null then
    insert into public.connect_manager_assignments
      (user_id, country_code, manager_role, status, assigned_by)
    values
      (v_uid, v_inv.country_code, v_inv.invited_role, 'active', v_inv.invited_by)
    returning id into v_assignment_id;
  else
    update public.connect_manager_assignments
       set status = 'active', assigned_by = v_inv.invited_by, updated_at = now()
     where id = v_assignment_id;
  end if;

  insert into public.access_audit(actor_id, action, resource, resource_id, country_code, metadata)
  values (
    v_uid,
    'connect_manager_invitation_accepted',
    'connect_manager_invitations',
    v_inv.id::text,
    v_inv.country_code,
    jsonb_build_object('role', v_inv.invited_role, 'email', v_email, 'assignment_id', v_assignment_id)
  );

  return jsonb_build_object(
    'ok', true,
    'country_code', v_inv.country_code,
    'role', v_inv.invited_role,
    'assignment_id', v_assignment_id
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.audit_connect_africa_change()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare
  v_row jsonb;
  v_country text;
  v_id text;
  v_action text;
begin
  v_row := case when TG_OP='DELETE' then to_jsonb(OLD) else to_jsonb(NEW) end;
  v_country := coalesce(v_row->>'country_code', v_row->>'origin_country_code', v_row->>'destination_country_code');
  v_id := v_row->>'id';
  v_action := 'connect_africa.' || lower(TG_OP);
  insert into public.access_audit(actor_id,action,resource,resource_id,country_code,metadata)
  values (auth.uid(),v_action,TG_TABLE_NAME,v_id,v_country,jsonb_build_object('operation',TG_OP));
  if TG_OP='DELETE' then return OLD; end if;
  return NEW;
end;
$function$

CREATE OR REPLACE FUNCTION public.audit_connect_manager_assignment()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare
  v_action text;
  v_row public.connect_manager_assignments;
begin
  if tg_op = 'DELETE' then
    v_row := old;
    v_action := 'manager_assignment_deleted';
  elsif tg_op = 'INSERT' then
    v_row := new;
    v_action := 'manager_assignment_created';
  else
    v_row := new;
    v_action := 'manager_assignment_updated';
  end if;

  insert into public.access_audit (
    actor_id, action, resource, resource_id, country_code, metadata
  ) values (
    auth.uid(),
    v_action,
    'connect_manager_assignments',
    v_row.id::text,
    v_row.country_code,
    jsonb_build_object(
      'manager_user_id', v_row.user_id,
      'manager_role', v_row.manager_role,
      'status', v_row.status
    )
  );

  if tg_op = 'DELETE' then return old; end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.audit_connect_manager_invitation()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare
  v_actor uuid;
  v_action text;
  v_row public.connect_manager_invitations%rowtype;
begin
  if TG_OP = 'DELETE' then
    v_row := OLD;
    v_actor := coalesce(auth.uid(), OLD.invited_by);
    v_action := 'connect_manager_invitation_deleted';
  else
    v_row := NEW;
    v_actor := coalesce(auth.uid(), NEW.invited_by);
    if TG_OP = 'INSERT' then
      v_action := 'connect_manager_invitation_created';
    elsif OLD.status is distinct from NEW.status then
      v_action := 'connect_manager_invitation_' || NEW.status;
    else
      return NEW;
    end if;
  end if;

  insert into public.access_audit(actor_id, action, resource, resource_id, country_code, metadata)
  values (
    v_actor,
    v_action,
    'connect_manager_invitations',
    v_row.id::text,
    v_row.country_code,
    jsonb_build_object('email', v_row.invited_email, 'role', v_row.invited_role, 'status', v_row.status)
  );

  if TG_OP = 'DELETE' then return OLD; end if;
  return NEW;
end;
$function$

CREATE OR REPLACE FUNCTION public.enforce_connection_request_transition()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
  if new.requester_business_id is distinct from old.requester_business_id
    or new.target_business_id is distinct from old.target_business_id
    or new.requested_by is distinct from old.requested_by
    or new.message is distinct from old.message
    or new.created_at is distinct from old.created_at then
    raise exception 'Os dados do pedido de conexão não podem ser alterados.';
  end if;
  if old.status <> 'pending' then
    raise exception 'Este pedido já foi tratado e não pode ser alterado.';
  end if;
  if public.is_platform_admin_only() then
    if new.status not in ('accepted','rejected','cancelled') then raise exception 'Transição inválida.'; end if;
  elsif exists (select 1 from public.businesses b where b.id=old.target_business_id and b.owner_id=auth.uid()) then
    if new.status not in ('accepted','rejected') then raise exception 'A empresa destinatária só pode aceitar ou recusar.'; end if;
  elsif exists (select 1 from public.businesses b where b.id=old.requester_business_id and b.owner_id=auth.uid()) then
    if new.status <> 'cancelled' then raise exception 'A empresa solicitante só pode cancelar o pedido.'; end if;
  else
    raise exception 'Sem autorização para alterar este pedido.';
  end if;
  new.updated_at=now();
  new.responded_at=now();
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.guard_business_opportunity_update()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
  if new.business_id is distinct from old.business_id
    or new.created_by is distinct from old.created_by
    or new.created_at is distinct from old.created_at then
    raise exception 'A propriedade e autoria da oportunidade não podem ser alteradas.';
  end if;
  if new.status='published' and old.status<>'published' then
    if not exists(select 1 from public.businesses b where b.id=new.business_id and b.owner_id=auth.uid() and b.status='approved' and b.verification_status='verified') and not public.is_platform_admin_only() then
      raise exception 'Só empresas aprovadas e verificadas podem publicar oportunidades.';
    end if;
    new.published_at=coalesce(new.published_at,now());
  end if;
  new.updated_at=now();
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.guard_investment_interest_workflow()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
begin
 if TG_OP='INSERT' then
  if NEW.status<>'pending' or NEW.requester_user_id is distinct from auth.uid() then
   raise exception 'Investment interest requests must start as pending and belong to the authenticated requester' using errcode='42501';
  end if;
 elsif TG_OP='UPDATE' then
  if NEW.opportunity_id is distinct from OLD.opportunity_id or NEW.investor_profile_id is distinct from OLD.investor_profile_id or NEW.requester_user_id is distinct from OLD.requester_user_id then
   raise exception 'Investment interest request ownership cannot be changed' using errcode='42501';
  end if;
 end if;
 return NEW;
end;
$function$

CREATE OR REPLACE FUNCTION public.guard_investment_opportunity_workflow()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare v_status text;
begin
 if TG_OP='UPDATE' then
  if NEW.investor_profile_id is distinct from OLD.investor_profile_id or NEW.created_by is distinct from OLD.created_by then
   raise exception 'Investment opportunity ownership cannot be transferred' using errcode='42501';
  end if;
 end if;
 select verification_status into v_status from public.investor_profiles where id=NEW.investor_profile_id and user_id=NEW.created_by;
 if not found then raise exception 'Investor profile does not belong to the opportunity owner' using errcode='42501'; end if;
 if NEW.status='published' and v_status<>'verified' then
  raise exception 'A verified investor profile is required to publish opportunities' using errcode='42501';
 end if;
 return NEW;
end;
$function$

CREATE OR REPLACE FUNCTION public.guard_investor_profile_verification()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
begin
 if not public.is_platform_admin_only() then
  if TG_OP='INSERT' and NEW.verification_status <> 'pending' then
   raise exception 'Investor verification can only be assigned by a platform administrator' using errcode='42501';
  end if;
  if TG_OP='UPDATE' and NEW.verification_status is distinct from OLD.verification_status then
   raise exception 'Investor verification can only be changed by a platform administrator' using errcode='42501';
  end if;
 end if;
 return NEW;
end;
$function$

CREATE OR REPLACE FUNCTION public.guard_new_connection_request()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
  if exists(
    select 1 from public.business_connections c
    where c.status='active'
      and ((c.company_a_id=least(new.requester_business_id,new.target_business_id)
        and c.company_b_id=greatest(new.requester_business_id,new.target_business_id)))
  ) then
    raise exception 'Estas empresas já possuem uma conexão comercial activa.';
  end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.guard_opportunity_participant_transition()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
  if new.opportunity_id is distinct from old.opportunity_id
    or new.business_id is distinct from old.business_id
    or new.requested_by is distinct from old.requested_by
    or new.message is distinct from old.message
    or new.created_at is distinct from old.created_at then
    raise exception 'Os dados da candidatura não podem ser alterados.';
  end if;
  if old.status <> 'pending' then raise exception 'Esta candidatura já foi tratada.'; end if;
  if public.is_platform_admin_only() then
    if new.status not in ('accepted','rejected','withdrawn') then raise exception 'Transição inválida.'; end if;
  elsif exists(select 1 from public.businesses b join public.business_opportunities o on o.business_id=b.id where o.id=old.opportunity_id and b.owner_id=auth.uid()) then
    if new.status not in ('accepted','rejected') then raise exception 'A empresa responsável só pode aceitar ou recusar a candidatura.'; end if;
  elsif exists(select 1 from public.businesses b where b.id=old.business_id and b.owner_id=auth.uid()) then
    if new.status <> 'withdrawn' then raise exception 'A empresa candidata só pode retirar a candidatura.'; end if;
  else
    raise exception 'Sem autorização para alterar esta candidatura.';
  end if;
  new.updated_at=now();
  new.responded_at=now();
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.notify_connection_request_created()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare target_owner uuid;
begin
  select owner_id into target_owner from public.businesses where id=new.target_business_id;
  insert into public.notifications(recipient_id,actor_id,business_id,event_type,entity_table,entity_id,title,body,metadata)
  values(target_owner,new.requested_by,new.target_business_id,'connection_request','connection_requests',new.id::text,'Novo pedido de conexão','Uma empresa pretende estabelecer uma relação comercial contigo.',jsonb_build_object('connection_request_id',new.id));
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.notify_opportunity_participant()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare owner_id uuid;
begin
  select b.owner_id into owner_id from public.business_opportunities o join public.businesses b on b.id=o.business_id where o.id=new.opportunity_id;
  insert into public.notifications(recipient_id,actor_id,business_id,event_type,entity_table,entity_id,title,body,metadata)
  values(owner_id,new.requested_by,new.business_id,'opportunity_application','opportunity_participants',new.id::text,'Nova manifestação de interesse','Uma empresa manifestou interesse numa oportunidade publicada.',jsonb_build_object('opportunity_id',new.opportunity_id,'participant_id',new.id));
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.notify_opportunity_participant_status()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare applicant_owner uuid;
begin
  if new.status is distinct from old.status and new.status in ('accepted','rejected') then
    select owner_id into applicant_owner from public.businesses where id=new.business_id;
    insert into public.notifications(recipient_id,actor_id,business_id,event_type,entity_table,entity_id,title,body,metadata)
    values(applicant_owner,auth.uid(),new.business_id,'opportunity_application_update','opportunity_participants',new.id::text,
      case when new.status='accepted' then 'Interesse aceite' else 'Interesse recusado' end,
      case when new.status='accepted' then 'A empresa responsável aceitou a tua manifestação de interesse.' else 'A empresa responsável não avançou com esta manifestação de interesse.' end,
      jsonb_build_object('opportunity_id',new.opportunity_id,'participant_id',new.id,'status',new.status));
  end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.prevent_profile_role_self_change()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if new.role is distinct from old.role and not public.is_platform_admin() then
    raise exception 'Only platform administrators can change profile roles';
  end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.set_business_catalog_item_updated_at()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
begin
  new.updated_at = now();
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.sync_business_connection_after_accept()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  requester_owner uuid;
  target_owner uuid;
  company_low uuid;
  company_high uuid;
begin
  if new.status='accepted' and old.status='pending' then
    select owner_id into requester_owner from public.businesses where id=new.requester_business_id;
    select owner_id into target_owner from public.businesses where id=new.target_business_id;
    company_low=least(new.requester_business_id,new.target_business_id);
    company_high=greatest(new.requester_business_id,new.target_business_id);
    insert into public.business_connections(company_a_id,company_b_id,source_request_id,status)
    values(company_low,company_high,new.id,'active')
    on conflict(company_a_id,company_b_id) do update set status='active',updated_at=now();
    insert into public.notifications(recipient_id,actor_id,business_id,event_type,entity_table,entity_id,title,body,metadata)
    values
      (requester_owner,auth.uid(),new.requester_business_id,'connection_accepted','connection_requests',new.id::text,'Pedido de conexão aceite','A outra empresa aceitou o teu pedido de conexão.',jsonb_build_object('connection_request_id',new.id)),
      (target_owner,auth.uid(),new.target_business_id,'connection_accepted','connection_requests',new.id::text,'Conexão comercial estabelecida','A conexão comercial foi estabelecida.',jsonb_build_object('connection_request_id',new.id))
    on conflict do nothing;
  end if;
  return new;
end;
$function$
